20	pub async fn call_tool(engine: &mut McpEngine, name: &str, args: Value) -> Result<Value, String> {
21	    let args = crate::request_context::public_args(args);
22	    let root = crate::server::resolve_request_project_root(engine)
23	        .ok_or("no initialized project for MCP request")?;
24	    crate::request_context::validate(&root, &args)?;
25	    if is_policy_tool(name) {
26	        if let Err(e) = engine.ensure_policy_fresh().await {
27	            tracing::warn!("ensure_policy_fresh failed (tool {name} continues): {e}");
28	            engine.ensure_initialized().await?;
29	            engine.reopen_if_replaced().await?;
30	        }
31	    } else {
32	        engine.ensure_initialized().await?;
33	        engine.reopen_if_replaced().await?;
34	    }
35	    let (args, _, _) = crate::server::prepare_call_args(engine, name, args);
36	    let result = {
37	        let mut guard = engine.lock_ax().await;
38	        let ax = guard.as_mut().ok_or("ax not initialized")?;
39	        ToolHandler::call_tool(ax, name, args).await?
40	    };
41	    Ok(crate::server::record_policy_delivery(engine, result))
42	}

